export type PageView = {
  path: string
  userAgent: string
  timestamp: string
}

/**
 * Records a page view with the analytics service.
 * Call this from `after()` so it does not delay the response.
 */
export async function logPageView(
  event: Omit<PageView, 'timestamp'>
): Promise<void> {
  const payload: PageView = {
    ...event,
    timestamp: new Date().toISOString(),
  }

  const endpoint = process.env.ANALYTICS_ENDPOINT
  if (!endpoint) {
    console.info('analytics:page_view', payload)
    return
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    throw new Error(`Analytics request failed with status ${response.status}`)
  }
}

